  summary = 'Students establish the field''s key terms, stakes, and reading practices across multicultural, postcolonial, ethnic, diasporic, and transnational literary study. The course examines how empire produced knowledge and representation, how anti-colonial writing imagines resistance and decolonization, and how nation, language, race, diaspora, Indigenous sovereignty, the Black Atlantic, borderlands, gender, memory, genre, global markets, critical methods, and scholarly ethics shape comparative literary analysis.',
  data = $mpocjson${"slug": "multicultural-postcolonial-literature", "title": "Multicultural / Postcolonial Literature", "description": "Students establish the field's key terms, stakes, and reading practices across multicultural, postcolonial, ethnic, diasporic, and transnational literary study. The course examines how empire produced knowledge and representation, how anti-colonial writing imagines resistance and decolonization, and how nation, language, race, diaspora, Indigenous sovereignty, the Black Atlantic, borderlands, gender, memory, genre, global markets, critical methods, and scholarly ethics shape comparative literary analysis.", "topics": [{"id": "67dfb231-0c56-4c6a-9218-2829c04b308d", "type": "topic", "title": "Field Foundations: Multicultural, Postcolonial, Ethnic, and Diaspora Literature", "description": "Establish the field's key terms, stakes, and reading practices across multicultural, postcolonial, ethnic, diasporic, and transnational literary study.", "children": [{"id": "0cda0aa3-b12f-4933-b566-9e542ddb8438", "type": "subtopic", "title": "Key field terms", "children": [{"id": "890dbc26-d8ee-4192-967c-1363a25233a9", "type": "concept", "title": "Postcolonial"}, {"id": "6a1967e4-7eca-4f5c-90bf-a2f0fe04afd4", "type": "concept", "title": "Decolonial"}, {"id": "717059af-f947-4f47-9f65-9a5e7ae1b82e", "type": "concept", "title": "Multicultural"}, {"id": "352c2eca-bb30-40e3-a38d-31b79ced6ce9", "type": "concept", "title": "Diaspora and transnationalism"}], "description": "Gist: Students learn the vocabulary that organizes the course while also treating each term as historically contested."}, {"id": "bc82062c-d82d-438b-938b-0440c5bacec0", "type": "subtopic", "title": "Why literature matters here", "children": [{"id": "b8a5ff5a-5164-4f36-8420-d0f858b7014b", "type": "concept", "title": "Representation"}, {"id": "e5ebc9a0-98ca-4230-9b75-151bd817807d", "type": "concept", "title": "Aesthetic form"}, {"id": "a86ac21b-30f2-481d-9b53-37f282a60ce7", "type": "concept", "title": "Historical witness"}, {"id": "ac73c4c7-613e-4887-8550-29ee960b5c1a", "type": "concept", "title": "Counter-memory"}], "description": "Gist: Literary texts let students see how power is lived through language, form, memory, desire, and everyday life."}, {"id": "3f50624c-f4fc-43b2-84e9-349034852924", "type": "subtopic", "title": "Reading across difference", "children": [{"id": "ed5e5d7f-6720-4476-b901-81c5cca43d87", "type": "concept", "title": "Close reading"}, {"id": "5b87c4cf-7bf2-4aa8-92b3-7d3797df1df0", "type": "concept", "title": "Contextual research"}, {"id": "fce36942-caad-449a-8a78-1f27cb1337bb", "type": "concept", "title": "Avoiding flattening comparisons"}], "description": "Gist: The course begins with interpretive humility, context, and evidence-based attention to cultural specificity."}]}, {"id": "5490b499-bd4f-4a70-bcc5-7772d6bebdac", "type": "topic", "title": "Colonialism, Empire, and Colonial Discourse", "description": "Study how empire produced knowledge, hierarchy, language, law, and literary representation.", "children": [{"id": "820ab44f-70e0-4d5d-b9f0-b0a7b45ea39b", "type": "subtopic", "title": "Colonial knowledge systems", "children": [{"id": "a13de232-c6ae-4564-ba60-3beac489177e", "type": "concept", "title": "Orientalism"}, {"id": "b713511e-2b11-4495-a84b-efa483ff214c", "type": "concept", "title": "Ethnography"}, {"id": "62cad803-c95d-474f-9085-25bee987e43f", "type": "concept", "title": "Missionary and travel writing"}, {"id": "4a7f8373-614c-405b-b2d8-2703376ad556", "type": "concept", "title": "Administrative knowledge"}], "description": "Gist: Students examine how empire classified people, places, languages, religions, and cultures."}, {"id": "440240d0-a178-458e-a5f7-317d6dd012a0", "type": "subtopic", "title": "Representation and hierarchy", "children": [{"id": "004e2721-4298-477d-9a9d-887f1b609677", "type": "concept", "title": "Exoticism"}, {"id": "7a0d77df-dbe1-419f-8cda-582da588160d", "type": "concept", "title": "Civilizing mission"}, {"id": "91786d4f-1dd2-4f06-9de4-4f6936f7219a", "type": "concept", "title": "Othering"}, {"id": "cf62f54a-5aa1-4884-a0bc-34d391976ec5", "type": "concept", "title": "Racial hierarchy"}], "description": "Gist: Colonial writing often naturalized domination through recurring images, plots, and stereotypes."}, {"id": "590c4d8d-d979-4a85-9bf7-a5b7c6afe7ac", "type": "subtopic", "title": "Reading colonial archives critically", "children": [{"id": "1359e837-f403-4f47-a83c-6cbf8f96afec", "type": "concept", "title": "Archival gaps"}, {"id": "5710a8c9-4516-49ef-adc5-77dc64f3d3de", "type": "concept", "title": "Voice and mediation"}, {"id": "55091804-a7f9-4f62-b475-672a15a74cec", "type": "concept", "title": "Counter-archives"}], "description": "Gist: Students learn to read official and literary archives for both evidence and silence."}]}, {"id": "a2560de6-eb90-4863-823f-0c74cd59fd67", "type": "topic", "title": "Anti-Colonial Writing and Decolonization", "description": "Examine writing as resistance, political imagination, and critique during anti-colonial and decolonizing movements.", "children": [{"id": "017c113c-eb0a-4464-b204-ac009aac6a97", "type": "subtopic", "title": "Resistance and political imagination", "children": [{"id": "fbd57105-e890-4eb8-88af-110c7133eddd", "type": "concept", "title": "National liberation"}, {"id": "cbfa837a-e5cf-4b9a-b019-4c1a93ff0ce5", "type": "concept", "title": "Revolutionary rhetoric"}, {"id": "5a37d31d-c74d-4538-a0d0-5de49b4825a0", "type": "concept", "title": "Public intellectuals"}, {"id": "6fa8ad9d-d8ac-4d8d-bfbb-b18e7379d877", "type": "concept", "title": "Collective voice"}], "description": "Gist: Anti-colonial writing contests empire while imagining new futures and publics."}, {"id": "c8026d70-a55e-4b19-ad4c-8c8a63d9eed7", "type": "subtopic", "title": "Decolonization and its limits", "children": [{"id": "2a52a4da-3d29-4bd5-b326-deb80292866c", "type": "concept", "title": "Neocolonialism"}, {"id": "28527e58-5c6c-48c6-951c-e23fea185b5b",